CREATE FUNCTION app_handover_note_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) - 'acknowledged_at') IS DISTINCT FROM (to_jsonb(OLD) - 'acknowledged_at') THEN
    RAISE EXCEPTION 'handover_note versions are immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER handover_note_immutable BEFORE UPDATE ON "handover_note" FOR EACH ROW EXECUTE FUNCTION app_handover_note_immutable();
